class RetryableError(Exception):
    pass

def load(times=3):
    for i in range(times):
        try:
            return do_io()
        except RetryableError:
            if i == times - 1:
                raise
    return None

import json, pathlib

def load_json(path, default=None):
    p = pathlib.Path(path)
    if not p.exists():
        return default
    try:
        return json.loads(p.read_text(encoding='utf-8'))
    except json.JSONDecodeError as e:
        raise ValueError(f'invalid JSON in {p.name}: {e}') from e

import csv

def sum_column(path, column):
    total = 0.0
    with open(path, newline='', encoding='utf-8') as f:
        for i, row in enumerate(csv.DictReader(f), start=2):
            raw = (row.get(column) or '').strip()
            if not raw:
                continue
            try:
                total += float(raw)
            except ValueError as e:
                raise ValueError(f'row {i}: {column}={raw!r} is not a number') from e
    return total

def parse_log(path):
    good, bad = [], 0
    with open(path, encoding='utf-8', errors='replace') as f:
        for line in f:
            parts = line.split(' ', 2)
            if len(parts) < 3 or not parts[0].strip():
                bad += 1
                continue
            good.append({'ts': parts[0], 'level': parts[1], 'msg': parts[2].strip()})
    return good, bad

import json, pathlib

class ConfigError(Exception):
    pass

def load_config(path, required=('db_url',)):
    p = pathlib.Path(path)
    if not p.exists():
        raise ConfigError(f'config not found: {p}')
    try:
        data = json.loads(p.read_text(encoding='utf-8'))
    except json.JSONDecodeError as e:
        raise ConfigError(f'invalid JSON at line {e.lineno}: {e.msg}') from e
    missing = [k for k in required if not data.get(k)]
    if missing:
        raise ConfigError(f'missing required keys: {", ".join(missing)}')
    return data

from datetime import date
import csv

def clean(path):
    kept, skipped = [], []
    with open(path, newline='', encoding='utf-8') as f:
        for i, row in enumerate(csv.DictReader(f), start=2):
            raw = (row.get('date') or '').strip()
            try:
                y, m, d = raw.split('-'); date(int(y), int(m), int(d))
                kept.append(row)
            except Exception as e:
                skipped.append((i, raw, type(e).__name__))
    return kept, skipped
